157			_, _, err := s.SubmitResult(student, "e1", Passed)
158			if err == nil || !strings.Contains(err.Error(), "不存在") {
159				t.Fatalf("学生 %q 不存在，提交应明确拒绝，得到 %v", student, err)
160			}
161			if !strings.Contains(err.Error(), "学生") {
162				t.Fatalf("学生 %q 找不到时应明确报告学生不存在，得到 %v", student, err)
163			}
164			// 不能借用 "s1" 的修读，也不能补建记录。
