167			}
168			if got := s.Enrollment(student, "e1"); got != nil {
169				t.Fatalf("不应为学生 %q 补建修读，得到 %+v", student, got)
170			}
171			if s.Dirty() {
172				t.Fatalf("被拒绝的提交不应产生变更（学生 %q）", student)
173			}
174		}
175	
176		// 学生存在但修读编号带各种前后空白：应报该学生名下不存在该修读。
177		for _, enrID := range []string{" e1", "e1 ", " e1 ", "\te1\t", "　e1　"} {
178			s, _ := mustLoadWhitespace(t, d)
179			_, _, err := s.SubmitResult("s1", enrID, Passed)
180			if err == nil || !strings.Contains(err.Error(), "不存在") {
181				t.Fatalf("修读 %q 不存在于 s1 名下，提交应明确拒绝，得到 %v", enrID, err)
182			}
183			if !strings.Contains(err.Error(), "s1") {
184				t.Fatalf("错误应点名学生 s1 名下不存在该修读，得到 %v", err)
185			}
186			if got := s.Enrollment("s1", "e1"); got == nil || got.Result != Enrolled {
187				t.Fatalf("修读 %q 被拒绝后 \"e1\" 不应变化，得到 %+v", enrID, got)
188			}
189			if got := s.Enrollment("s1", enrID); got != nil {
190				t.Fatalf("不应补建修读 %q，得到 %+v", enrID, got)
191			}
192			if s.Dirty() {
193				t.Fatalf("被拒绝的提交不应产生变更（修读 %q）", enrID)
194			}
195		}
196	}
197	
198	// TestSubmitResultWhitespaceIdempotentAndConflictRules 准确命中带空白的
199	// 修读后沿用现有规则：重复提交相同结果返回原记录且不产生变更；已提交
200	// 结果改提另一结果拒绝并保留原结果。
201	func TestSubmitResultWhitespaceIdempotentAndConflictRules(t *testing.T) {
202		s, _ := mustLoadWhitespace(t, whitespaceBase())
203	
204		if _, changed, err := s.SubmitResult(" s1 ", "e1", Passed); err != nil || !changed {
205			t.Fatalf("首次提交通过应成功，changed=%v err=%v", changed, err)
206		}
207		s.dirty = false // 只看后续提交是否产生新变更
208	
209		// 重复提交相同结果：幂等返回原记录，不再产生变更。
210		e, changed, err := s.SubmitResult(" s1 ", "e1", Passed)
211		if err != nil || changed {
212			t.Fatalf("重复提交相同结果应幂等返回，changed=%v err=%v", changed, err)
213		}
214		if e.StudentID != " s1 " || e.Result != Passed {
215			t.Fatalf("幂等返回的应是原记录，得到 %+v", e)
216		}
217		if s.Dirty() {
218			t.Fatal("幂等重复提交不应产生变更")
219		}
220	
221		// 改提另一结果：拒绝并保留通过。
222		if _, _, err := s.SubmitResult(" s1 ", "e1", Failed); err == nil {
223			t.Fatal("已提交通过后改提未通过应被拒绝")
224		}
225		if got := s.Enrollment(" s1 ", "e1"); got.Result != Passed {
226			t.Fatalf("拒绝后应保留通过结果，得到 %+v", got)
227		}
228		if s.Dirty() {
229			t.Fatal("被拒绝的改提不应产生变更")
230		}
231	}
