package credit

import (
	"strings"
	"testing"
)

// 本文件为“选课登记按用户给出的完整编号确定修读归属”这项行为提供回归
// 保障。记录文件可以合法保存带前后空白的学生编号、要求编号与修读编号，
// Load 按原样接受（见 whitespace_submit_load_test.go 的 mustLoadWhitespace），
// enroll 也必须如此：
