	}
	if e.ReqID != " r1 " {
		t.Fatalf("修读应指向完整要求编号 \" r1 \"，得到 %+v", e)
	}
	if got := s.Requirement("s1", "r1"); got == nil || got.CourseID != "c1" {
		t.Fatalf("要求 \"r1\" 不应被改写，得到 %+v", got)
